packs['sd-3::math::Simple Fractions'] = [
  makeQ("A round pizza is sliced into 4 equal slices. If you eat 1 slice, what fraction of the pizza did you eat?",
    "Sebuah piza bundar dipotong menjadi 4 bagian sama besar. Jika kamu memakan 1 potong, berapa bagian pecahan yang kamu makan?",
    ["1/4 (one quarter)", "1/2 (one half)", "3/4 (three quarters)", "1/3 (one third)"],
    ["1/4 (seperempat)", "1/2 (setengah)", "3/4 (tiga perempat)", "1/3 (sepertiga)"], 0,
    "Eating 1 out of 4 equal parts is written as the fraction 1/4.", "Memakan 1 dari 4 potong sama besar ditulis dalam bentuk pecahan 1/4."),
  makeQ("In the fraction 3/5, what is the number 3 called?",
    "Pada pecahan 3/5, angka 3 di bagian atas disebut:",
    ["The numerator (pembilang)", "The denominator (penyebut)", "The quotient", "The remainder"],
    ["Pembilang (numerator)", "Penyebut (denominator)", "Hasil bagi", "Sisa bagi"], 0,
    "The numerator is the top number representing the parts considered.", "Angka di atas garis pecahan disebut pembilang (numerator)."),
  makeQ("In the fraction 2/7, what is the number 7 called?",
    "Pada pecahan 2/7, angka 7 di bagian bawah disebut:",
    ["The denominator (penyebut)", "The numerator (pembilang)", "The multiplier", "The divisor"],
    ["Penyebut (denominator)", "Pembilang (numerator)", "Faktor kali", "Faktor bagi"], 0,
    "The denominator indicates the total number of equal parts in the whole.", "Angka di bawah garis pecahan disebut penyebut (denominator)."),
  makeQ("Which fraction is larger: 1/2 or 1/4?",
    "Pecahan manakah yang nilainya lebih besar: 1/2 atau 1/4?",
    ["1/2 is larger", "1/4 is larger", "Both are equal", "Cannot be determined"],
    ["1/2 lebih besar", "1/4 lebih besar", "Keduanya sama besar", "Tidak dapat ditentukan"], 0,
    "Dividing a whole into 2 parts gives larger pieces than dividing into 4 parts: 1/2 > 1/4.", "Membagi benda menjadi 2 bagian menghasilkan potongan yang lebih besar dibanding membaginya jadi 4: 1/2 > 1/4."),
  makeQ("What is 1/5 + 2/5?",
    "Berapakah hasil dari 1/5 + 2/5?",
    ["3/5", "3/10", "2/25", "1/5"],
    ["3/5", "3/10", "2/25", "1/5"], 0,
    "With identical denominators, add the numerators: 1/5 + 2/5 = 3/5.", "Karena penyebutnya sudah sama (5), cukup jumlahkan pembilangnya: 1 + 2 = 3, sehingga menjadi 3/5."),
  makeQ("What is 4/6 - 1/6?",
    "Berapakah hasil dari 4/6 - 1/6?",
    ["3/6", "5/6", "3/12", "4/6"],
    ["3/6", "5/6", "3/12", "4/6"], 0,
    "4/6 minus 1/6 equals 3/6 (which simplifies to 1/2).", "4/6 dikurangi 1/6 menghasilkan 3/6 (atau disederhanakan menjadi 1/2)."),
  makeQ("Which fraction is equivalent to 1/2?",
    "Pecahan manakah di bawah ini yang senilai dengan 1/2?",
    ["2/4", "2/5", "1/3", "3/5"],
    ["2/4", "2/5", "1/3", "3/5"], 0,
    "Multiplying top and bottom of 1/2 by 2 gives 2/4.", "Mengalikan pembilang dan penyebut 1/2 dengan 2 menghasilkan pecahan senilai 2/4."),
  makeQ("A chocolate bar has 8 equal squares. Sarah eats 5 squares. What fraction remains?",
    "Sebatang cokelat memiliki 8 kotak sama besar. Sarah memakan 5 kotak. Berapa bagian pecahan yang tersisa?",
    ["3/8", "5/8", "1/2", "3/5"],
    ["3/8", "5/8", "1/2", "3/5"], 0,
    "8/8 - 5/8 = 3/8 of the chocolate bar remains.", "8/8 - 5/8 menyisakan 3/8 batang cokelat."),
  makeQ("Which fraction represents a whole integer equal to 1?",
    "Pecahan manakah yang nilainya tepat sama dengan 1 utuh?",
    ["4/4", "3/4", "5/4", "1/4"],
    ["4/4", "3/4", "5/4", "1/4"], 0,
    "When numerator equals denominator (e.g. 4/4), the fraction equals 1 whole.", "Ketika nilai pembilang dan penyebut sama besar (misal 4/4), pecahannya bernilai 1 utuh."),
  makeQ("There are 10 apples in a bowl. 3 are red and the rest are green. What fraction of the apples are green?",
    "Ada 10 apel di keranjang. 3 berwarna merah dan sisanya hijau. Berapa bagian pecahan apel yang berwarna hijau?",
    ["7/10", "3/10", "5/10", "4/10"],
    ["7/10", "3/10", "5/10", "4/10"], 0,
    "10 - 3 = 7 green apples, which is 7/10 of the total.", "10 - 3 = 7 apel hijau, sehingga pecahannya adalah 7/10.")
];

